default.shell:
$mismatchCount = 0

$key = Get-Item -LiteralPath 'HKLM:\Software\Microsoft\Windows\Currentversion\Policies\System' -ErrorAction SilentlyContinue
$current = $null
if ($key) { $current = $key.GetValue('InactivityTimeoutSecs', $null, 'DoNotExpandEnvironmentNames') }
if (-not ($current -is [int] -and [BitConverter]::ToUInt32([BitConverter]::GetBytes($current), 0) -eq [uint32]$ODV_inactivity_timeout_seconds)) {
    Write-Output 'Mismatch: HKLM:\Software\Microsoft\Windows\Currentversion\Policies\System [InactivityTimeoutSecs]'
    $mismatchCount++
}

if ($mismatchCount -gt 0) { exit 1 }
exit 0

steps.shell:
$ErrorActionPreference = 'Stop'
trap { Write-Output $_.Exception.Message; exit 1 }

if (-not (Test-Path -LiteralPath 'HKLM:\Software\Microsoft\Windows\Currentversion\Policies\System')) {
    New-Item -Path 'HKLM:\Software\Microsoft\Windows\Currentversion\Policies\System' -Force | Out-Null
}
New-ItemProperty -LiteralPath 'HKLM:\Software\Microsoft\Windows\Currentversion\Policies\System' -Name 'InactivityTimeoutSecs' -Value $ODV_inactivity_timeout_seconds -PropertyType DWord -Force | Out-Null
exit 0
